  (2, 2, '아이퍼스', null, '2025-03-14', 6983390, 0, 6983390, '[{"금액": 6983390, "품목명": "유럽 특허 출원 심사 및 OA 대응"}]'::jsonb, 'ACTIVITY', 'IP_ACTIVITY', 0.820, '특허 출원·심사 단계는 지식재산 창출 활동비', '[]', null, '[]'::jsonb, '확정', '현금', '계좌송금', 3, null),
